def icon(name: str) -> str:
    """Render an allowlisted decorative icon, falling back to a generic model icon."""
    return ICONS.get(name, ICONS["box"]).replace(
        "<svg", '<svg class="icon" aria-hidden="true" focusable="false"', 1
    )
